CAT = "afspIncome"; SEG = "INC"
# AFTR outline 2.2 to 2.7 and 2.9: wages and tips, interest, dividends and foreign accounts, Social
# Security and retirement income, IRAs (IR-2025-111 limits for 2026), unemployment, alimony, capital
# gains (Rev. Proc. 2025-32 4.03). Pubs. 17, 525, 531, 550, 590-A, 590-B, 915, 504, 523, 544. Tax year 2026.
_prov = 20000 + 12000 // 2
_ss = min(12000 // 2, (_prov - 25000) // 2); assert _ss == 500
_ira = 7500 + 1100; assert _ira == 8600
_ded = 7500 * (91000 - 86000) // 10000; assert _ded == 3750
_carry = 8000 - 3000; assert _carry == 5000
_home = 600000 - 500000; assert _home == 100000

Q = [
("Tips that a server reported to her employer during 2026 are included in her:",
 "Form W-2 wages", ["Schedule C receipts", "Schedule 1 other income", "Form 1099-NEC income"],
 "Reported tips are wages: the employer withholds on them and includes them in box 1 of Form W-2, with Social Security tips in box 7 (Pub. 531). Only unreported tips go on Form 4137."),
("An employee must report tips to the employer for any month in which cash and charge tips reach:",
 "$20", ["$50", "$100", "$10"],
 "Tips of $20 or more in a month at one job must be reported to the employer by the 10th of the next month (Pub. 531). Tips under $20 are still taxable income."),
("Schedule B is required when a taxpayer's taxable interest or ordinary dividends for the year are:",
 "Over $1,500", ["Over $600", "Over $1,000", "Over $10"],
 "Part I or II of Schedule B must be filed when taxable interest or ordinary dividends exceed $1,500. $10 is the usual threshold for a payer to issue Form 1099-INT or 1099-DIV."),
("A client's only foreign bank account peaked at $15,000 in 2026. Besides checking the box in Schedule B Part III, the client must file:",
 "FinCEN Form 114", ["Form 8938 only", "Form 3520", "No other form"],
 "An FBAR, FinCEN Form 114, is required when foreign accounts total more than $10,000 at any time in the year. Form 8938's thresholds are far higher; Form 3520 is for foreign trusts and large foreign gifts."),
("To be taxed at capital gain rates, a qualified dividend on common stock requires holding the stock more than 60 days during:",
 "The 121-day period around the ex-date", ["The 90 days before payment", "The calendar year of payment", "The 60 days after purchase"],
 "The stock must be held more than 60 days during the 121-day period that begins 60 days before the ex-dividend date (Pub. 550). Otherwise the dividend is ordinary."),
("Sue, single, has $20,000 of other income and $12,000 of Social Security benefits in 2026. The taxable part of her benefits is:",
 f"${_ss:,}", ["$6,000", "$1,000", "$0"],
 "Provisional income is $20,000 + half of $12,000 = $26,000, which is $1,000 over the $25,000 base. Taxable is the smaller of half the benefits ($6,000) or half the excess ($500)."),
("On a joint return, part of Social Security benefits becomes taxable once provisional income is over:",
 "$32,000", ["$25,000", "$44,000", "$34,000"],
 "The first base amount is $32,000 for married filing jointly and $25,000 for most other filers; $44,000 is the joint second base above which up to 85% can be taxed (Pub. 915)."),
("Which early distribution is still subject to the 10% additional tax?",
 "IRA withdrawal at 56 after a layoff", ["401(k) payout at 56 after a layoff", "IRA payment after total disability", "IRA payment to a beneficiary"],
 "The age-55 separation-from-service exception applies only to employer plans such as a 401(k), not to IRAs (Pub. 590-B). Disability and death are exceptions for both."),
("Eve is 52. What is the most she can contribute to her IRAs for 2026 if she has enough compensation?",
 f"${_ira:,}", ["$7,500", "$8,500", "$8,000"],
 "For 2026 the IRA limit is $7,500, plus a $1,100 catch-up for age 50 and older (IR-2025-111): $8,600 across all traditional and Roth IRAs."),
("The last day to make a 2026 IRA contribution is:",
 "April 15, 2027", ["December 31, 2026", "October 15, 2027", "January 15, 2027"],
 "A contribution for 2026 can be made up to the return due date, not counting extensions (Pub. 590-A). An extension to October does not extend this deadline."),
("Dan, single and covered by a workplace plan, has 2026 MAGI of $86,000 and puts $7,500 in a traditional IRA. His deduction is:",
 f"${_ded:,}", ["$7,500", "$5,000", "$0"],
 "For 2026 his phaseout range is $81,000 to $91,000 (IR-2025-111). He is halfway, so half the $7,500 is deductible: $3,750."),
("A single filer has 2026 MAGI of $170,000. How much can she contribute to a Roth IRA for 2026?",
 "Nothing", ["$7,500", "$3,750", "$1,100"],
 "The 2026 Roth phaseout for single filers runs from $153,000 to $168,000 (IR-2025-111). At $170,000 she is above the range."),
("Jill has no earnings in 2026, but her husband earns $90,000 and they file jointly. Jill can fund an IRA because:",
 "The spousal IRA rule applies", ["Wages are not required", "She is a 401(k) participant", "Her husband adopts her IRA"],
 "On a joint return, a spouse with little or no compensation can contribute based on the couple's combined taxable compensation (Pub. 590-A)."),
("Which early traditional IRA withdrawal at age 40 avoids the 10% additional tax?",
 "$8,000 for a first home", ["$8,000 for a car loan", "$8,000 for a wedding", "$8,000 for credit card debt"],
 "Up to $10,000 in a lifetime withdrawn to buy, build or rebuild a first home is an exception to the additional tax (Pub. 590-B). The amount is still taxable income."),
("For a taxpayer born in 1953, required minimum distributions from a traditional IRA must begin for the year she turns:",
 "73", ["70 1/2", "72", "75"],
 "Under SECURE 2.0, the required beginning age is 73 for people born from 1951 through 1959 (Pub. 590-B). Age 75 applies to those born in 1960 or later."),
("A worker received $9,000 of unemployment compensation in 2026. For federal tax, the benefits are:",
 "Fully taxable", ["Taxable over $2,400", "Tax-free", "Taxable at half"],
 "Unemployment compensation is fully taxable and reported to the recipient on Form 1099-G (Pub. 525). The partial exclusion applied only to 2020."),
("To have federal income tax withheld from unemployment benefits, the recipient gives the paying agency:",
 "Form W-4V", ["Form W-4", "Form W-4P", "Form 1040-ES"],
 "Form W-4V, Voluntary Withholding Request, lets a recipient have 10% withheld from unemployment compensation. Without it, estimated payments may be needed."),
("Under a 2016 divorce decree never modified, a former husband pays alimony in 2026. For him, the payments are:",
 "Deductible", ["Not deductible", "Taxable income", "Partly deductible"],
 "Alimony under agreements executed before 2019 stays deductible by the payer and taxable to the recipient unless a later modification adopts the new rules (Pub. 504)."),
("A divorce agreement signed in 2022 requires cash alimony. For the person who receives it in 2026, the alimony is:",
 "Not taxable income", ["Taxable income", "Taxable above $15,000", "Self-employment income"],
 "For divorce or separation instruments executed after 2018, alimony is neither deductible by the payer nor included in the recipient's income (Pub. 504)."),
("A single filer has an $8,000 net capital loss for 2026. How much of the loss carries over to 2027?",
 f"${_carry:,}", ["$8,000", "$3,000", "$0"],
 "Up to $3,000 of net capital loss offsets ordinary income each year ($1,500 married filing separately). The other $5,000 carries forward with its character."),
("A woman sells stock her father gave her, at a gain. Her holding period includes:",
 "Her father's holding period", ["Only the time since the gift", "Only half of his time", "No time at all"],
 "When the donee's basis is figured from the donor's basis, as for a gain on gifted property, the donor's holding period is added to the donee's (Pub. 550)."),
("For 2026, a single filer's long-term capital gains are taxed at 0% to the extent taxable income does not exceed:",
 "$49,450", ["$50,400", "$48,350", "$66,200"],
 "Rev. Proc. 2025-32 (section 4.03) sets the 2026 maximum zero rate amount at $49,450 for single filers. $66,200 is the head of household figure."),
("A married couple who owned and lived in their home for 10 years sell it in 2026 for a $600,000 gain. The taxable gain is:",
 f"${_home:,}", ["$350,000", "$0", "$250,000"],
 "Joint filers who meet the two-of-five-years ownership and use tests may exclude up to $500,000 of gain on a main home (Pub. 523). $600,000 - $500,000 = $100,000."),
("Sales of stock whose basis the broker reported to the IRS are listed on Form 8949 and then totaled on:",
 "Schedule D", ["Schedule B", "Schedule 1", "Form 4797"],
 "Form 8949 lists each capital asset sale, and its totals carry to Schedule D (Form 1040). Form 4797 is for business property."),
]
